// unsigned int Stack // 32bits long, so 12+12 ->24bits OK
//
// Stack -> [Stack2][Stack1]
// so PC_Pointer -> Stack &0x3ff; STACK >>= 12;
//
// but this would incorrectly clear out STACK2

